def transform(grid):
    h, w = len(grid), len(grid[0])
    oh, ow = h // 2, w // 2

    # Output background = BL background
    output = [[9] * ow for _ in range(oh)]

    # TR objects (4s) layer first
    for r in range(oh):
        for c in range(ow):
            if grid[r][9 + c] == 4 and output[r][c] == 9:
                output[r][c] = 4

    # TL objects (6s) layer next
    for r in range(oh):
        for c in range(ow):
            if grid[r][c] == 6 and output[r][c] == 9:
                output[r][c] = 6

    # BL objects (5s) layer next
